// friday13.cs — Friday the 13th experiments with the proleptic Gregorian calendar

// 1. Find the earliest Friday the 13th starting from 0001-01-01
DateOnly? earliest = null;
for (int year = 1; year <= 9999; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateOnly(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            earliest = d;
            break;
        }
    }
    if (earliest.HasValue) break;
}

Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd} ({earliest!.Value.DayOfWeek})");

// 2. Count Friday the 13ths in a full 400-year Gregorian cycle (years 1–400)
int count = 0;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        if (new DateOnly(year, month, 13).DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");

// 3. Bonus: distribution by month across the 400-year cycle
var byMonth = new int[12];
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        if (new DateOnly(year, month, 13).DayOfWeek == DayOfWeek.Friday)
            byMonth[month - 1]++;
    }
}

Console.WriteLine("\nFriday-the-13th count by month (400-year cycle):");
for (int m = 0; m < 12; m++)
    Console.WriteLine($"  {new DateOnly(2000, m + 1, 1):MMMM,-12} {byMonth[m]}");

